def build():
    with open(os.path.join(SCRIPT_DIR, 'index.html'), 'r', encoding='utf-8') as f:
        template = f.read()

    for lang, config in LANGUAGES.items():
        html = template

        # Fix lang attribute
        html = html.replace('<html lang="en">', f'<html lang="{lang}">')

        # Fix asset paths for subdirectory
        html = html.replace('href="css/styles.css"', 'href="../css/styles.css"')
        html = html.replace('src="js/main.js"', 'src="../js/main.js"')
        html = html.replace('href="logo-icon.svg"', 'href="../logo-icon.svg"')
        html = html.replace('href="assets/', 'href="../assets/')

        # Fix canonical and og URLs
        html = html.replace('<link rel="canonical" href="https://konforme.io/"', f'<link rel="canonical" href="https://konforme.io/{lang}/"')
        html = html.replace('"og:url" content="https://konforme.io/"', f'"og:url" content="https://konforme.io/{lang}/"')
        html = html.replace('"og:locale" content="en_GB"', f'"og:locale" content="{config["locale"]}"')

        # Fix language switcher active state
        html = html.replace('<a href="/" class="active">English</a>', '<a href="/">English</a>')
        # Match using href pattern since labels may contain HTML entities
        html = html.replace(f'<a href="/{lang}/">', f'<a href="/{lang}/" class="active">')

        # Fix switcher button label
        html = html.replace(\
            '            EN\n            <svg',
            f'            {lang.upper()}\n            <svg')

        # Fix privacy link for subdirectory
        html = html.replace('href="/privacy"', 'href="/privacy"')  # stays absolute

        # Apply content translations
        for old, new in config['replacements']:
            html = html.replace(old, new)

        # Apply mid-page CTA translations
        for old, new in MID_CTA.get(lang, []):
            html = html.replace(old, new)

        # Apply cookie banner translations
        for old, new in COOKIE_BANNER.get(lang, []):
            html = html.replace(old, new)

        # Write output
        out_dir = os.path.join(SCRIPT_DIR, lang)
        os.makedirs(out_dir, exist_ok=True)
        out_path = os.path.join(out_dir, 'index.html')
        with open(out_path, 'w', encoding='utf-8') as f:
            f.write(html)
        print(f'  ✓ {lang}/index.html')


if __name__ == '__main__':
    print('Building translated pages...')
    build()
    print('Done!')
